  "strategy3Title": "策略3：50/200移动平均线",
  "strategy3Timeframe": "4H - 周线",
  "strategy3Setup": "设置：使用EMA 50和EMA 200。",
  "strategy3Entry": "进场：等待回调至EMA 50。",
  "strategy3Exit": "出场：只要价格高于EMA 50就持有仓位。",
  "strategy3Tips": "提示：趋势跟随策略。在趋势中效果最佳。",
  "strategy4Title": "策略4：RSI背离 + S/R",
  "strategy4Timeframe": "1H - 日线",
  "strategy4Setup": "设置：在关键区域寻找RSI背离。",
  "strategy4Entry": "进场：等待蜡烛形态确认。",
  "strategy4Exit": "出场：TP = 下一个阻力/支撑。SL = 低于/高于S/R区域。",
  "strategy4Tips": "提示：隐藏背离在趋势中更强。",
  "strategy5Title": "策略5：价格行为 - Pin Bar",
  "strategy5Timeframe": "4H - 日线",
  "strategy5Setup": "设置：识别高反应区域。",
  "strategy5Entry": "进场：看涨Pin Bar = 买入。看跌Pin Bar = 卖出。",
  "strategy5Exit": "出场：SL = Pin Bar影线下方/上方。TP1 = 2倍Pin Bar大小。",
  "strategy5Tips": "提示：高时间框架的Pin Bar更可靠。",
  "vBottomReversalName": "V形底（看涨反转）",
  "vBottomReversalDesc": "急速反转形态：持续下跌后价格形成尖锐的V形低点并强劲反弹。确认从看跌到看涨的趋势转变。",
  "vBottomReversalHTT_1": "Entry 1：在V形之前的阻力线向上突破时买入",
