  "vBottomReversalHTT_5": "确认：突破阻力时伴随成交量上升的看涨蜡烛",
  "vBottomContinuationName": "V形底（看涨延续）",
  "vBottomContinuationDesc": "上升趋势内的延续形态：价格做出小V形回调并通过突破前期高点恢复上升。用于加仓。",
  "vBottomContinuationHTT_1": "Entry 1：在V形前最后一个高点向上突破时买入",
  "vBottomContinuationHTT_2": "Entry 2：在该高点（现为支撑）回测时买入",
  "vBottomContinuationHTT_3": "止损：V形低点下方",
  "vBottomContinuationHTT_4": "止盈 1 和 2：投影V形之前的摆动距离",
  "vBottomContinuationHTT_5": "确认：与更大的上升趋势对齐（EMA50 上升）",
  "expandingPatternsAscWedgeName": "上升扩张楔形",
  "expandingPatternsAscWedgeDesc": "成熟上升趋势中的看跌反转形态。两条线都上升但发散,产生不断增长的波动性。下方线突破触发强劲修正。止损位于最近高点之上,目标 = 楔形高度向下投影。",
  "expandingPatternsBullContName": "看涨扩张三角形(延续)",
  "expandingPatternsBullContDesc": "看涨延续形态。上升扩张楔形在上升趋势内充当积累区。向上突破确认延续。T1 = 最小高度,T2 = 完整投影高度。",
  "expandingPatternsBearRevName": "看跌扩张三角形(看涨反转)",
  "expandingPatternsBearRevDesc": "下跌趋势末期的看涨反转形态。卖压减弱,买家在不断上升的低点出现。向上突破 = 新的看涨周期。双重入场,止损位于最近低点之下。",
  "expandingPatternsBearContName": "看跌扩张三角形(延续)",
  "expandingPatternsBearContDesc": "看跌延续形态。明确下跌趋势中的波动暂停,然后恢复下跌。向下突破确认延续,目标等于形态高度。",
  "expandingPatternsBearRevDownName": "看跌扩张三角形(看跌反转)",
  "expandingPatternsBearRevDownDesc": "上升趋势之后的看跌反转。更高的高点逐渐减弱,买家失去控制。下方支撑突破确认趋势变化。",
