  "xmM08A2": "5 手",
  "xmM08A3": "0.714 手",
  "xmM08A4": "没有上限",
  "xmM08Why": "5,000 ÷（100 × 70）= 0.714。保证金那一项消失了，只剩下本金对你想承受的波动幅度。",
  "xmM09Title": "点差、隔夜利息、滑点与跳空",
  "xmM09Corrects": "用「干净」的价格来算目标。",
  "xmM09Idea": "一旦缓冲以价格单位来衡量，交易成本就不再是会计细节，而成了缓冲的一部分。",
  "xmM09S1H": "量级",
  "xmM09S1B": "黄金 0.25 美元的点差，五手就是每笔 125 美元。开锁再解锁一共四笔交易：500 美元。相对实算案例里 671.85 美元的可用保证金，光是执行就吃掉 74 %。",
  "xmM09S2H": "图表上看不到的东西",
  "xmM09S2B": "点差在宏观数据发布与周末收盘前会扩大。隔夜利息每晚收取，锁仓时通常两条腿都收。周日开盘的跳空可能整个越过你的强平位：强平按第一个可成交价格执行，而不是你算出来的那个。",
  "xmM09Q": "为什么开盘跳空比连续交易中同等幅度的走势更糟？",
  "xmM09A1": "因为隔夜利息会成倍增加",
  "xmM09A2": "因为强平按第一个可成交价格执行，而它可能远低于预期",
  "xmM09A3": "因为经纪商周日会提高保证金",
  "xmM09A4": "因为非交易时段不计算保证金比例",
  "xmM09Why": "中间根本没有可供成交的价格。所以即便设有强平线，余额仍可能变成负数。",
  "xmM10Title": "存活：为什么问题不在目标",
  "xmM10Corrects": "用目标处的盈利来评价一套计划。",
  "xmM10Idea": "带杠杆的计划要看过程，而不是终点。正确的问题是：走完这段路而不动用缓冲的概率有多大。",
  "xmM10S1H": "破产公式",
  "xmM10S1B": "无漂移时，先达到 +a 而不是先亏掉 −b 的概率是 b ÷ (a + b)。缓冲 7.66 美元、目标 260 美元时结果是 2.9 %。加上一个强劲上升趋势——每天 20 美元、日波动率 60 美元——概率升到 8.6 %：仍然是一套十次里失败九次的计划。",
  "xmM10F": "P = b ÷ (a + b)",
  "xmM10S2H": "取舍",
  "xmM10S2B": "减小入场规模会提高缓冲与概率，代价是同样的金额盈利需要更长的行情。这个取舍就是全部的决策，而它在第一笔委托时就定下了：之后不平仓就无法更改。",
  "xmM10S3H": "一致性检验",
  "xmM10S3B": "如果一套计划要求你在开始之前先把账户翻三倍，而你确实做得到，那这套计划就是多余的：重复做那件事本身能走得更远，而且从不经过追加保证金通知。任何依赖于「先解决一个比自身更难的问题」的计划，都是循环论证。",
  "xmM10Q": "缓冲 5 美元，目标 100 美元。无漂移时的大致概率是多少？",
  "xmM10A1": "50 %",
  "xmM10A2": "20 %",
  "xmM10A3": "5 %",
  "xmM10A4": "95 %",
  "xmM10Why": "5 ÷（100 + 5）= 4.8 %。缓冲与目标之间的不对称，对结果的影响远大于你选择的方向。",
  "xmM11Title": "合法存在的杠杆有多少，在哪里",
  "xmM11Corrects": "以为 1:500 在欧洲是个正常选项。",
  "xmM11Idea": "在欧盟，零售客户的黄金杠杆上限是 20:1。任何 1:500 或 1:1000 都意味着一家该框架之外的机构，以及随之而来的一切。",
  "xmM11S1H": "上限",
